	// An offset into the int8 bank is a **byte**; the tail is halves, because
	// the build that reads it is the fp16 one.
	qkvBank, outBank, tailBank := g.qkvN()*c.NEmbd*2, c.NEmbd*c.GateWidth()*2, 0
	unit := 2
	if g.q8 {
