			qkvTail: uint32((i*perBank + qkvBank) / 2),
			out:     uint32((i*perBank + qkvBank + tailBank) / unit),
			gQ:      base,
			gK:      base + uint32(c.HeadDim),
			gIQ:     base + uint32(2*c.HeadDim),
			gIK:     base + uint32(2*c.HeadDim+c.IdxDim),
		}
	}
	return nil
}

